        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Which one of the following is not a natural ecosystem ? (A) Pond ecosystem (B) Grassland ecosystem (C) Forest ecosystem (D) Cropland ecosystem 12. A uniform magnetic field exists in the plane of paper as shown in the diagram. In this field, an electron (e) and a positron (p+) enter as shown. The electron and positron experience forces : (A) both pointing into the plane of the paper. (B) both pointing out of the plane of the paper. (C) pointing into the plane of the paper and out of the plane of the paper respectively. (D) pointing out of the plane of the paper and into the plane of the paper respectively. 13. How will the image formed by a convex lens be affected, if the upper half of the lens is wrapped with a black paper ? (A) The size of the image formed will be one-half of the size of the image due to complete lens. (B) The image of upper half of the object will not be formed. (C) The brightness of the image will reduce. (D) The lower half of the inverted image will not be formed. 14. The phenomena of light involved in the formation of rainbow are : (A) Refraction, reflection and dispersion (B) Refraction, dispersion and internal reflection (C) Reflection, dispersion and internal reflection (D) Refraction, dispersion, scattering and total internal reflection 15-31/5/3 10', 'short_answer', 1, '2024', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'An old pe rson is suffering from an eye defect caused by weakening of ciliary muscles and diminishing flexibility of the eye lens. If the defect of vision is ‘a’ which can be corrected by lens ‘b’, then ‘a’ and ‘b’ respectively are : (A) hypermetropia and convex lens (B) presbyopia and bifocal lens (C) myopia and concave lens (D) myopia and bifocal lens', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'The phenomenon responsible for making the smoke particles visible when a beam of sunlight enters a smoke filled room through a narrow hole is : (A) scattering of light (B) dispersion of light (C) reflection of light (D) internal reflection of light', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'A convex lens forms an 8 0 cm long image of a 2 0 cm long object which is kept at a distance of 6 0 cm from the optical centre of the lens. If the object and the image are on the same side of the lens, find (i) the nature of the image, (ii) the position of the image, and (iii) the focal length of the lens. 3', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'A convex mirror used for rear view on an automobile has a focal length of 15 m. If a 3 m high bus is located at 6 0 m from the mirror, use mirror formula to determine the position and size of the image of the bus as seen in the mirror. 3', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'A candle flame is placed in front of the reflecting surface of a convex mirror of focal length f. If the distance of the flame from the pole of the mirror is ‘f ’, its image is formed : (A) at infinite distance from the mirror (B) behind the mirror at the principal focus (C) behind the mirror at a distance 2f (D) behind the mirror at a distance f 2', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Select the correct statement from the following : (A) The size of the molecules of air is larger than the wavelength of visible light. (B) The blue light has a wavelength about 1∙8 times greater than that of red light. (C) When sunlight passes through the fine particles in air, they scatter the blue colour of visible light more strongly than red. (D) The light of red colour is scattered the most by fog or smoke.', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'A person is suffering from an eye defect in which the far point of the eye is much nearer than infinity. Name the defect of vision the person is suffering from. List two main causes of this defect. Write the type of the corrective lens and draw a ray diagram to show the function of the corrective lens. 3', 'short_answer', 3, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'What do the symbols given below represent in an electric circuit ? Write one function of each. 2 (i) (ii) { } 31/4/2 Page 26 of 32 35. 3             : (a)   K     ,   AB       ? (b)              AB         36. (a)           : 3 (i)  A       B      (ii)  B   C     (b)         ‘A’   ,  ‘C’         ‘B’   ,  ‘A’   ‘C’        { } 31/4/2 Page 27 of 32 P.T.O. 35. 3 On the basis of the given circuit arrangement, answer the following questions : (a) What happens to the rod AB when the key K is closed and why ? (b) Name and state the rule that determines this behaviour of the rod AB in the above situation. 36. (a) Observe the given ray diagram and compare : 3 (i) the speed of light in medium A and the speed of light in medium B. (ii) the optical densities of medium B and medium C. (b) Draw a ray diagram for refraction where the optical density of medium ‘A’ becomes equal to the optical density of medium ‘C’ and optical density of medium ‘B’ is greater than the optical density of medium ‘A’ and medium ‘C’. { } 31/4/2 Page 28 of 32', 'short_answer', 5, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) Relate the speed of light in the given medium with its optical density. 2 (b) Using the information given in the table below, arrange the medium A, B and C in the ascending order of their optical density. Medium Speed of light (m/s) A 2.25  108 B 2  108 C 2.08  108 { } 31/5/1 Page 26 of 32', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
