        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) (i) A compound ‘X’ having two carbon atoms in its molecule turns blue litmus red and 5 – 8% solution of ‘X’ in water is widely used as a preservative. Identify the compound ‘X’ and write its structure. 1 1 2 (ii) Compare its pH nature with a mineral acid. 1 2 (iii) ‘X’ on reacting with alcohols produces sweet smelling compounds, used in making perfumes. Name the reaction and write its chemical equation. 1 1 2 (iv) When sodium carbonate is added to ‘X’, a colourless gas is produced which turns lime water milky. Write the chemical equation for the reaction giving the name of the salt produced. 1 1 2 OR (b) (i) Differentiate between saturated and unsaturated hydrocarbons by giving one example each, with a structural formula. (ii) Write the method of converting an unsaturated hydrocarbon into a saturated hydrocarbon. Name the industry where this reaction is commonly used. (iii) Write the name and structure of a hydrocarbon having double bond and four carbon atoms in its one molecule. 5', 'short_answer', 5, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Given below are the structures of some hydrocarbons. Select the two structures which are related to each other from the given options : (i) HHH – C – C – C = C – HH H H H     (ii) H H H H – C – C – C – C – HH H H H H         (iii) (iv) H H H – C – C – C = C – HC HHH l   (A) (i) and (iv) (B) (ii) and (iv) (C) (ii) and (iii) (D) (i) and (iii)', 'short_answer', 1, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either option (A) or (B) : (A) (i) Carbon cannot form C4+ cation and C4– anion. Explain. (ii) Define homologous series of carbon compounds. Why are the melting and boiling points of C4H10 higher than C3H8 or C2H6 ? (iii) What happens when ethanol is heated with acidified potassium dichromate ? 2+2+1 OR (B) (i) How would you name the following : I. CH 3 – CH2 – C|H = = O II. CH 3 – C   CH (ii) When ethanol reacts with ethanoic acid in the presence of conc. H2SO4, a substance with sweet smell is produced. Answer the following : I. State the class of compounds to which the sweet smelling compounds belong. II. Write the chemical equation for the reaction. (iii) Why soaps do not produce foam with hard water ? 2+2+1 { } 31/4/1 Page 24 of 32  -  ( )', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Which of the following set of compounds does not belong to same homologous series ? 1 (A) CH 4 and C4H10 (B) C 2H6 and C3H8 (C) C 3H8 and C5H12 (D) C 4H8 and C5H12 { } 31/5/3 Page 16 of 32', 'short_answer', 1, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Alcohol forms a homologous series with general formula CnH2n + 1 –OH and –OH group as functional group. Ethanol is commonly called alcohol and is used in alcoholic drinks. It is good solvent, used in medicines, cough syrups, tonics etc. 1+1+2 (a) Write structural formula and name of 4th member of alcohol homologous series. (b) What happens when ethanol is heated with alkaline KMnO4 ? Write chemical equation involved. (c) Write the chemical equation of reaction of ethanol with ethanoic acid in the presence of concentrated H2SO4. Write the name of this reaction. OR (c) What happens when ethanol is heated with excess concentrated sulphuric acid at 443 K ? Write chemical equation involved. What is the role of concentrated sulphuric acid in this reaction ? { } 31/5/1 Page 22 of 32', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : Blood plasma transports carbon dioxide in dissolved for m, while oxygen is transported by respiratory pigments. Reason (R) : Carbon dioxide is more soluble in water than in oxygen. 1', 'short_answer', 1, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : There are large number of compounds with many carbon atoms linked to each other. Reason (R) : Carbon-Carbon bond is very strong and stable. 1 [ ] 31/3/2 Page 18 of 31', 'short_answer', 2, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either (a) or (b) : (a) (i) What is homologous series ? Which two of the following organic compounds belong to the same homologous series ? C2H4, C4H10, C3H4, C4H8 (ii) Write the product(s) in the following reactions : (I) CH3 – CH2 – OH + CH3COOH ⎯⎯⎯⎯ → (II) C2H5OH + O2 ⎯⎯⎯⎯→ (iii) Why does micelle formation take place when soap is added to water ? 2+2+1=5 OR (b) (i) Name the following compounds : (I) 3 3– C – CH O CH  (II) H – C – C C – HH H    (ii) Name the reaction which is commonly used in the conversion of vegetable oils to fats. (iii) Why is the melting point of C4H10 higher than C3H8 ? (iv) What happens when a piece of sodium is dropped into ethanol ? (v) Write the products in the following reaction : 5×1=5 CH3COOC2H5 + NaOH ⎯⎯ → Acid Burning [ ] 31/3/1 Page 22 of 31', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, '(a) Select from the following the members of same homologous series : (1) HHH – C – C – C = O HH H   (2)      HH – C – C – C – H OHH H (3)   OHH – C – C – C – OH HH H (4)   HHHH – C – C – C – C = O HHH H (b) What happens to (i) the melting point, and (ii) the solubility of compounds as the molecular mass of the compounds in a homologous series increases ? 2', 'short_answer', 2, '2025', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either (a) or (b) : (a) A carbon compound ‘P’ of molecular formula C 2H6O is found to be neutral when tested with red and blue litmus. A gas that burns with a pop sound is produced when sodium metal reacts with compound ‘P’. (i) Identify the compound ‘P’. (ii) The carbon compound ‘P’ is heated with conc. H 2SO4 at 443 K to produce compound ‘Q’. (I) Write the chemical equation for the reaction. (II) What is the role of conc. H2SO4 in this reaction ? (iii) What is likely to be observed on heating compound ‘P’ with ethanoic acid with an acid as a catalyst ? Write the chemical equation for the reaction. 1+2+2=5 OR (b) (i) Write the structural formula of benzene. (ii) State the reason why carbon can neither form C4+ cation nor C4– anion. (iii) What type of bond is formed between carbon and hydrogen ? (iv) How is ethanol converted to ethanoic acid ? (v) Complete the following chemical equation : 5×1=5 CH3COOC2H5 + NaOH ⎯⎯ → [ ] 31/2/1 Page 24 of 31', 'short_answer', 3, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Assertion (A) : Carbon shows the property of catenation. Reason (R) : C – C bond is weak due to its small size. 1 [ ] 31/2/2 Page 18 of 31', 'short_answer', 1, '2026', 'medium');
        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
