        INSERT INTO quiz_questions (quiz_id, question_text, type, marks, source_year, difficulty)
        VALUES (v_quiz_id, 'Attempt either subpart (a) or (b) : (a) (i) Define catenation. Why does carbon show catenation ? (ii) Define homologous series. Give examples of two homologues whose molecular mass differ by 14 amu. (iii) Why do soaps not work well in hard water ? 2+2+1=5 OR (b) (i) Why do covalent compounds have low melting and boiling points ? (ii) Name the reagent that can convert ethanol to ethanoic acid. (iii) Why is ethanoic acid a weaker acid than mineral acids ? (iv) Define esterification reaction. (v) What are ‘Micelles’ ? 51=5 [ ] 31(B) Page 20 of 27', 'short_answer', 3, '2026', 'medium');
